SELECT id, symbol, side, status, quantity, entry_price, stop_loss, take_profit, exit_price, realized_pnl, close_reason, signal_id, exit_signal_id, opened_at, closed_at, CRC32(CONCAT_WS('|', entry_reason, exit_reason)) AS reason_crc, LENGTH(entry_reason) AS entry_len, LEFT(exit_reason, 600) AS exit_reason FROM crypto_ai.paper_position WHERE id IN (182,172,162,158,143,137) ORDER BY id;